52: /**
53:  * Provides the capability for starting/stopping/restarting/uninstalling Hudson.
54:  *
55:  * <p>
56:  * The steps to perform these operations depend on how Hudson is launched,
57:  * so the concrete instance of this method (which is VM-wide singleton) is discovered
58:  * by looking up a FQCN from the system property "hudson.lifecycle".
59:  * (This may be set to a class defined in a plugin,
60:  * in which case the singleton switches during startup.)
61:  * @author Kohsuke Kawaguchi
62:  * @since 1.254
63:  */
64: public abstract class Lifecycle {
65:     private static Lifecycle INSTANCE = null;
66: 
67:     /**
68:      * Gets the singleton instance.
69:      */
70:     @NonNull
71:     public static synchronized Lifecycle get() {
72:         if (INSTANCE == null) {
73:             Lifecycle instance;
74:             String p = SystemProperties.getString("hudson.lifecycle");
75:             if (p != null) {
76:                 try {
77:                     ClassLoader cl = Jenkins.get().getPluginManager().uberClassLoader;
78:                     instance = (Lifecycle) cl.loadClass(p).getDeclaredConstructor().newInstance();
79:                 } catch (NoSuchMethodException e) {
80:                     NoSuchMethodError x = new NoSuchMethodError(e.getMessage());
81:                     x.initCause(e);
82:                     throw x;
83:                 } catch (InstantiationException e) {
84:                     InstantiationError x = new InstantiationError(e.getMessage());
85:                     x.initCause(e);
86:                     throw x;
87:                 } catch (IllegalAccessException e) {
88:                     IllegalAccessError x = new IllegalAccessError(e.getMessage());
89:                     x.initCause(e);
90:                     throw x;
91:                 } catch (ClassNotFoundException e) {
92:                     LOGGER.log(Level.FINE, e, () -> "Failed to load " + p + " so will try again later");
93:                     instance = new PlaceholderLifecycle();
94:                 } catch (InvocationTargetException e) {
95:                     Throwable t = e.getCause();
96:                     switch (t) {
97:                         case RuntimeException runtimeException -> throw runtimeException;
98:                         case IOException ioException -> throw new UncheckedIOException(ioException);
99:                         case Exception exception -> throw new RuntimeException(t);
100:                         case Error error -> throw error;
101:                         case null, default -> throw new Error(e);
102:                     }
103:                 }
104:             } else {
105:                 if (Functions.isWindows()) {
106:                     instance = new Lifecycle() {
107:                         @Override
108:                         public void verifyRestartable() throws RestartNotSupportedException {
109:                             throw new RestartNotSupportedException(
110:                                     "Default Windows lifecycle does not support restart.");
111:                         }
112:                     };
113:                 } else if (System.getenv("SMF_FMRI") != null && System.getenv("SMF_RESTARTER") != null) {
114:                     // when we are run by Solaris SMF, these environment variables are set.
115:                     instance = new SolarisSMFLifecycle();
116:                 } else if (System.getenv("NOTIFY_SOCKET") != null) {
117:                     // When we are running under systemd with Type=notify, this environment variable is set.
118:                     instance = new SystemdLifecycle();
119:                 } else {
120:                     // if run on Unix, we can do restart
121:                     try {
122:                         instance = new UnixLifecycle();
123:                     } catch (final Throwable t) {
124:                         LOGGER.log(Level.WARNING, "Failed to install embedded lifecycle implementation", t);
125:                         instance = new Lifecycle() {
126:                             @Override
127:                             public void verifyRestartable() throws RestartNotSupportedException {
128:                                 throw new RestartNotSupportedException(
129:                                         "Failed to install embedded lifecycle implementation, so cannot restart: " + t, t);
130:                             }
131:                         };
132:                     }
133:                 }
134:             }
135:             assert instance != null;
136:             INSTANCE = instance;
137:         }
138: 
139:         return INSTANCE;
140:     }
141: 
142:     /**
143:      * If the location of {@code jenkins.war} is known in this life cycle,
144:      * return it location. Otherwise return null to indicate that it is unknown.
145:      *
146:      * <p>
147:      * When a non-null value is returned, Hudson will offer an upgrade UI
148:      * to a newer version.
149:      */
150:     public File getHudsonWar() {
151:         String war = SystemProperties.getString("executable-war");
152:         if (war != null && new File(war).exists())
153:             return new File(war);
154:         return null;
155:     }
156: 
157:     /**
158:      * Replaces jenkins.war by the given file.
159:      *
160:      * <p>
161:      * On some system, most notably Windows, a file being in use cannot be changed,
162:      * so rewriting {@code jenkins.war} requires some special trick. Override this method
163:      * to do so.
164:      */
165:     public void rewriteHudsonWar(File by) throws IOException {
166:         File dest = getHudsonWar();
167:         // this should be impossible given the canRewriteHudsonWar method,
168:         // but let's be defensive
169:         if (dest == null)  throw new IOException("jenkins.war location is not known.");
170: 
171:         // backing up the old jenkins.war before it gets lost due to upgrading
172:         // (newly downloaded jenkins.war and 'backup' (jenkins.war.tmp) are the same files
173:         // unless we are trying to rewrite jenkins.war by a backup itself
174:         File bak = new File(dest.getPath() + ".bak");
175:         if (!by.equals(bak))
176:             FileUtils.copyFile(dest, bak);
177: 
178:         FileUtils.copyFile(by, dest);
179:         // we don't want to keep backup if we are downgrading
180:         if (by.equals(bak)) {
181:             Files.deleteIfExists(Util.fileToPath(bak));
182:         }
183:     }
184: 
185:     /**
186:      * Can {@link #rewriteHudsonWar(File)} work?
187:      */
188:     public boolean canRewriteHudsonWar() {
189:         // if we don't know where jenkins.war is, it's impossible to replace.
190:         File f = getHudsonWar();
191:         if (f == null || !f.canWrite()) {
192:             return false;
193:         }
194:         File parent = f.getParentFile();
195:         if (parent == null || !parent.canWrite()) {
196:             return false;
197:         }
198:         return true;
199:     }
