201:     /**
202:      * If this life cycle supports a restart of Hudson, do so.
203:      * Otherwise, throw {@link UnsupportedOperationException},
204:      * which is what the default implementation does.
205:      *
206:      * <p>
207:      * The restart operation may happen synchronously (in which case
208:      * this method will never return), or asynchronously (in which
209:      * case this method will successfully return.)
210:      *
211:      * <p>
212:      * Throw an exception if the operation fails unexpectedly.
213:      */
214:     public void restart() throws IOException, InterruptedException {
215:         throw new UnsupportedOperationException();
216:     }
217: 
218:     /**
219:      * Can the {@link #restart()} method restart Hudson?
220:      *
221:      * @throws RestartNotSupportedException
222:      *      If the restart is not supported, throw this exception and explain the cause.
223:      */
224:     public void verifyRestartable() throws RestartNotSupportedException {
225:         // the rewriteHudsonWar method isn't overridden.
226:         if (!Util.isOverridden(Lifecycle.class, getClass(), "restart"))
227:             throw new RestartNotSupportedException("Restart is not supported in this running mode (" +
228:                     getClass().getName() + ").");
229:     }
